    int result;
    System.out.println(result);  // ERROR! Not initialized
}

// CORRECT - Initialize before use
public void calculate() {
    int result = 0;
    System.out.println(result);  // OK
}

// WRONG - Conditional initialization
public void process(boolean flag) {
    int value;
    if (flag) {
        value = 10;
    }
    System.out.println(value);  // ERROR! May not be initialized
}

// CORRECT - Always initialize
public void process(boolean flag) {
    int value = 0;  // Default
    if (flag) {
        value = 10;
    }
    System.out.println(value);  // OK
}
```

